"use client";
import React, { useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faCalendarXmark,
  faShieldHeart,
  faSuitcaseMedical,
} from "@fortawesome/free-solid-svg-icons";
import Destinations from "@/components/after-your-booking/destinations";
import postSubscribe from "@/services/subscribe";

const coverage = [
  {
    icon: faCalendarXmark,
    title: "Rescheduling",
    body: "Cancellation coverage is an essential part of travel insurance — make sure you're prepared in case delays, illness, or accidents prevent you from enjoying your planned trip. Protect yourself and your travel companions from trip cancellations caused by unexpected events.",
  },
  {
    icon: faShieldHeart,
    title: "Health Coverage",
    body: "Medical coverage is essential during emergencies. If you or your travel companion fall ill or get injured while traveling, you don't want to stress about medical expenses — this extends to dental emergencies too, where credit card coverage often falls short.",
  },
  {
    icon: faSuitcaseMedical,
    title: "Baggage Protection",
    body: "Even when everything goes smoothly, there are factors beyond your control. Having coverage for baggage loss or theft can make all the difference — an essential component of any travel insurance policy.",
  },
];

const faqs: { q: string; a: React.ReactNode }[] = [
  {
    q: "What does the Peace of Mind program cover?",
    a: "If your plans change, our Peace of Mind program gives you the flexibility to change dates, choose a different tour, or receive credit for a future trip — valid when booking with the same operator.",
  },
  {
    q: "How do I delay my booking and get Credit for Future Trips?",
    a: (
      <>
        <p className="tw-mt-0 tw-mb-2">
          Log in to your account and click on your booking to access your Booking
          Conversation Page. Select the &ldquo;Modify Booking&rdquo; option and
          follow the steps. If you need assistance, contact our Travel Experts —
          we&apos;re available 24/7!
        </p>
        <p className="tw-mt-0 tw-mb-0">
          <b className="tw-text-[#14101c]">Important:</b> if you postpone your
          booking, the Credit for Future Trips will only be valid with the
          operator you originally booked.
        </p>
      </>
    ),
  },
  {
    q: "Does the Peace of Mind Program apply to every tour?",
    a: (
      <>
        <p className="tw-mt-0 tw-mb-2 tw-font-semibold tw-text-[#14101c]">
          The Peace of Mind Program is available only for tours offered by certain
          operators.
        </p>
        <p className="tw-mt-0 tw-mb-0">
          Check the &quot;Your Peace of Mind Options&quot; section on the Tour
          Detail Page, just below the &quot;What&apos;s Included&quot; section.
          Alternatively, contact our Travel Experts for assistance.
        </p>
      </>
    ),
  },
  {
    q: "How much time do I have to redeem my Credit for Future Trips?",
    a: "The expiration dates for credit are set by the tour operators and can be found in the terms and conditions of your adventure.",
  },
  {
    q: "How can I change my booking?",
    a: (
      <>
        <p className="tw-mt-0 tw-mb-2">
          Visit your tour&apos;s Booking Conversation Page and click &ldquo;Modify
          Booking&rdquo; to:
        </p>
        <ul className="tw-m-0 tw-pl-5 tw-space-y-1">
          <li>Change your tour dates</li>
          <li>Choose a different tour (from the same operator)</li>
          <li>
            Receive Credit for Future Trips: use credit toward a future trip with
            the same operator.
          </li>
          <li>
            Cancel your tour: full refunds are not guaranteed, and fees may apply
            according to your operator&apos;s T&amp;Cs. Cancellations must be
            submitted in writing via &ldquo;Modify Booking&rdquo;.
          </li>
        </ul>
        <p className="tw-mt-2 tw-mb-0 tw-font-semibold tw-text-[#14101c]">
          Fees may apply.
        </p>
      </>
    ),
  },
];

const TravelInsurance = () => {
  const [subscribeLoading, setSubscribeLoading] = useState(false);
  const [subscribeMail, setSubscribeMail] = useState("");
  const [subscribeStatus, setSubscribeStatus] = useState("");
  const [subscribeErrorMessage, setSubscribeErrorMessage] = useState("");
  const isEmail = (email: string) =>
    /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,4}$/i.test(email);

  const subscribePost = async () => {
    if (!subscribeMail || !isEmail(subscribeMail)) {
      setSubscribeErrorMessage("Please specify a valid email address");
      setSubscribeStatus("error");
    } else {
      setSubscribeLoading(true);
      setSubscribeStatus("");
      await postSubscribe(subscribeMail).then(() => {
        setSubscribeMail("");
        setSubscribeStatus("success");
        setSubscribeLoading(false);
      });
    }
  };

  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-center"
          style={{ backgroundImage: "url('/images/couple.webp')" }}
          aria-hidden="true"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.5) 0%, rgba(20,16,28,0.6) 55%, rgba(20,16,28,0.82) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-24 md:tw-py-32">
          <div className="tw-max-w-[760px]">
            <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white/10 tw-border tw-border-solid tw-border-white/20 tw-px-4 tw-py-1.5 tw-text-[13px] tw-font-semibold tw-text-white tw-backdrop-blur">
              Travel Insurance
            </span>
            <h1 className="tw-mt-5 tw-text-[clamp(32px,5vw,56px)] tw-font-bold tw-tracking-tight tw-leading-[1.05] tw-text-white tw-m-0">
              Trip Protection &amp; Coverage
            </h1>
            <p className="tw-mt-5 tw-mb-0 tw-text-[17px] tw-leading-[1.6] tw-text-white/85 tw-max-w-[60ch]">
              Travel can be unpredictable, but with travel insurance from XCover via
              Cover Genius, you&apos;re protected no matter what happens. Focus less
              on the what-ifs and more on enjoying your organized adventure!
            </p>
          </div>
        </div>
      </section>

      {/* Reliable partner */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[820px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Your Reliable Travel Partner
          </h2>
          <div className="tw-mt-5 tw-space-y-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
            <p className="tw-m-0">
              When you&apos;re on an organized adventure, you&apos;re seeking
              unforgettable experiences, not unexpected setbacks! Travel insurance
              acts as your safety net — an affordable investment that could save you
              thousands in the event of an accident or unforeseen mishap.
            </p>
            <p className="tw-m-0">
              Picture this: your flight is canceled, an emergency calls you back
              home, or you require medical attention while abroad. These are just a
              few scenarios where XCover by Cover Genius steps in, providing tailored
              solutions and helping cover the associated expenses.
            </p>
            <p className="tw-m-0">
              Many health plans don&apos;t provide coverage abroad, and credit card
              insurance is often limited. That&apos;s why investing in quality travel
              insurance is a smart choice — providers like Cover Genius offer
              customized packages designed to meet your specific needs.
            </p>
          </div>
        </div>
      </section>

      {/* Coverage cards */}
      <section className="tw-pb-12 md:tw-pb-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-text-center tw-mb-10">
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              Insurance tailored for today&apos;s traveler
            </h2>
          </div>
          <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-3 tw-gap-5 lg:tw-gap-6">
            {coverage.map((card) => (
              <div
                key={card.title}
                className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-7 hover:tw-border-[#d8d2e1] hover:tw-shadow-lg tw-transition-all tw-duration-200"
              >
                <div className="tw-flex tw-h-14 tw-w-14 tw-items-center tw-justify-center tw-rounded-2xl tw-bg-[#854ec9]/10 tw-text-[#854ec9]">
                  <FontAwesomeIcon icon={card.icon} className="tw-text-2xl" />
                </div>
                <h3 className="tw-mt-4 tw-text-[18px] tw-font-bold tw-text-[#14101c] tw-m-0">
                  {card.title}
                </h3>
                <p className="tw-mt-2 tw-mb-0 tw-text-[14px] tw-leading-[1.6] tw-text-[#5d556c]">
                  {card.body}
                </p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* FAQ */}
      <section className="tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-text-center tw-mb-10">
            <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
              Commonly Asked Questions
            </h2>
          </div>
          <div className="tw-grid tw-grid-cols-1 md:tw-grid-cols-2 tw-gap-5 lg:tw-gap-6">
            {faqs.map((faq) => (
              <div
                key={faq.q}
                className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6"
              >
                <h3 className="tw-text-[16px] tw-font-bold tw-text-[#14101c] tw-mt-0 tw-mb-3">
                  {faq.q}
                </h3>
                <div className="tw-text-[14px] tw-leading-[1.7] tw-text-[#5d556c]">
                  {faq.a}
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Newsletter */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-relative tw-overflow-hidden tw-rounded-3xl tw-px-7 tw-py-12 md:tw-px-12 md:tw-py-14">
            <div
              className="tw-absolute tw-inset-0"
              style={{
                background:
                  "linear-gradient(120deg, #854ec9 0%, #6a3da4 60%, #4f2d7f 100%)",
              }}
              aria-hidden="true"
            />
            <div className="tw-relative tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-8 tw-items-center">
              <div>
                <h2 className="tw-text-[clamp(22px,3vw,30px)] tw-font-bold tw-tracking-tight tw-text-white tw-m-0">
                  Subscribe to Our Newsletter
                </h2>
                <p className="tw-mt-3 tw-mb-0 tw-text-[15px] tw-leading-[1.6] tw-text-white/85">
                  Enjoy savings of up to 50% on our tours! Gain exclusive access to
                  email-only offers for members.
                </p>
              </div>
              <div>
                {subscribeStatus === "error" && (
                  <div className="tw-mb-3 tw-rounded-xl tw-bg-white/15 tw-border tw-border-solid tw-border-white/30 tw-px-4 tw-py-3 tw-text-[14px] tw-font-medium tw-text-white">
                    {subscribeErrorMessage}
                  </div>
                )}
                {subscribeStatus === "success" && (
                  <div className="tw-mb-3 tw-rounded-xl tw-bg-white/15 tw-border tw-border-solid tw-border-white/30 tw-px-4 tw-py-3 tw-text-[14px] tw-font-medium tw-text-white">
                    Your registration has been received. We thank you.
                  </div>
                )}
                <div className="tw-flex tw-flex-col sm:tw-flex-row tw-gap-2.5">
                  <input
                    type="email"
                    id="insurance-subscribe-mail-input"
                    placeholder="Your email"
                    aria-label="Your email"
                    value={subscribeMail}
                    onChange={(e) => setSubscribeMail(e.target.value)}
                    className="tw-flex-1 tw-rounded-full tw-border tw-border-solid tw-border-white/30 tw-bg-white/95 tw-px-5 tw-py-3 tw-text-[15px] tw-text-[#14101c] tw-outline-none focus:tw-ring-2 focus:tw-ring-white/60"
                  />
                  <button
                    type="button"
                    disabled={subscribeLoading}
                    onClick={subscribePost}
                    className="tw-inline-flex tw-items-center tw-justify-center tw-gap-2 tw-bg-white hover:tw-bg-[#f3f1f7] disabled:tw-opacity-70 tw-text-[#854ec9] tw-font-semibold tw-text-[15px] tw-px-7 tw-py-3 tw-rounded-full tw-transition-colors"
                  >
                    {subscribeLoading ? "Loading..." : "Subscribe"}
                  </button>
                </div>
                <p className="tw-mt-3 tw-mb-0 tw-text-[12px] tw-leading-[1.5] tw-text-white/75">
                  By submitting this form, I agree to the TravelShop Booking{" "}
                  <a href="/terms-of-use" className="tw-font-semibold tw-text-white">
                    Terms of Use
                  </a>{" "}
                  and{" "}
                  <a href="/privacy-policy" className="tw-font-semibold tw-text-white">
                    Privacy Policy
                  </a>
                  .
                </p>
              </div>
            </div>
          </div>
        </div>
      </section>

      <Destinations />
    </main>
  );
};

export default TravelInsurance;
